import { Chunk } from "./Chunk";
import { Block } from "./blocks";
import type { TerrainGenerator } from "./TerrainGenerator";
import type { BlockPosition } from "./BlockPosition";
import type { WorldStorage } from "./WorldStorage";
import { logger } from "../util/logger";

/**
 * Holds all the chunks. Chunks are generated by the TerrainGenerator the
 * first time someone asks for them and then kept in memory (nothing is
 * saved to disk).
 */
export class World {
  private readonly chunks = new Map<string, Chunk>();

  /** `storage` is optional so tests can use a world that is never saved. */
  constructor(
    readonly generator: TerrainGenerator,
    private readonly storage?: WorldStorage,
  ) {}

  /**
   * Loads or generates a chunk. Don't keep the returned Chunk around: chunks
   * nobody is near get unloaded, and changes made to a stale Chunk object are
   * lost. Keep coordinates and call world.setBlock() when you need to change something.
   *
   * Throws if the chunk has a save file that cannot be read. The chunk is then
   * not cached, so the next call tries again (and no edits are overwritten).
   */
  getChunk(chunkX: number, chunkZ: number): Chunk {
    const key = `${chunkX},${chunkZ}`;
    let chunk = this.chunks.get(key);
    if (!chunk) {
      chunk = new Chunk(chunkX, chunkZ);
      this.generator.generate(chunk);
      const saved = this.storage?.load(chunkX, chunkZ);
      if (saved) chunk.applyEdits(saved);
      this.chunks.set(key, chunk);
    }
    return chunk;
  }

  /*
   * World coordinates -> chunk + position inside the chunk:
   *   chunk = x >> 4   (divide by 16, rounding down, works for negatives too)
   *   local = x & 15   (the remainder, always 0-15)
   */

  getBlockId(pos: BlockPosition): number {
    if (pos.y < 0 || pos.y > 255) return 0;
    return this.getChunk(pos.x >> 4, pos.z >> 4).getBlockId(pos.x & 15, pos.y, pos.z & 15);
  }

  getBlockMetadata(pos: BlockPosition): number {
    if (pos.y < 0 || pos.y > 255) return 0;
    return this.getChunk(pos.x >> 4, pos.z >> 4).getBlockMetadata(pos.x & 15, pos.y, pos.z & 15);
  }

  setBlock(pos: BlockPosition, blockId: number, metadata = 0): void {
    if (pos.y < 0 || pos.y > 255) return;
    this.getChunk(pos.x >> 4, pos.z >> 4).editBlock(pos.x & 15, pos.y, pos.z & 15, blockId, metadata);
  }

  /**
   * Writes every changed chunk to disk.
   * `failed` counts chunks that still have unsaved changes (they are retried on the next call).
   */
  saveDirtyChunks(): { saved: number; failed: number } {
    if (!this.storage) return { saved: 0, failed: 0 };
    let saved = 0;
    let failed = 0;
    for (const chunk of this.chunks.values()) {
      if (!chunk.dirty) continue;
      try {
        this.storage.save(chunk.x, chunk.z, chunk.getEdits() as Map<number, number>);
        chunk.dirty = false; // only after a successful write, so a failure is retried next time
        saved++;
      } catch (err) {
        failed++;
        logger.error(`Could not save chunk ${chunk.x},${chunk.z}: ${(err as Error).message}`);
      }
    }
    return { saved, failed };
  }

  /**
   * Forgets every chunk that is not in `keep` (a set of "x,z" keys), so memory
   * does not grow forever as players explore. Chunks with unsaved changes are
   * kept; they get unloaded after the next successful save.
   * Unloaded chunks are simply regenerated (plus their saved edits) when needed again.
   */
  unloadChunksExcept(keep: ReadonlySet<string>): number {
    let unloaded = 0;
    for (const [key, chunk] of this.chunks) {
      if (keep.has(key) || chunk.dirty) continue;
      this.chunks.delete(key);
      unloaded++;
    }
    return unloaded;
  }

  get loadedChunkCount(): number {
    return this.chunks.size;
  }

  /**
   * The y a player should stand at to be on top of the highest solid block
   * in this column. Water counts as solid so people don't spawn underwater.
   */
  getSpawnHeight(x: number, z: number): number {
    const chunk = this.getChunk(x >> 4, z >> 4);
    for (let y = 255; y >= 0; y--) {
      if (chunk.getBlockId(x & 15, y, z & 15) !== Block.Air) return y + 1;
    }
    return 64; // empty column (void world): pick something sane
  }
}
